-- Additive DEV-only hardening; no event/apply/reconcile changes and no browser writes.
CREATE FUNCTION public.gw_exchange_safe_fact(_value jsonb,_domain text,_owner public.gw_app) RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$
SELECT coalesce(jsonb_object_agg(x.key,CASE WHEN x.key='approval' THEN jsonb_build_object('role',x.value->>'role','approval_id',x.value->>'approval_id','approved_at',x.value->>'approved_at') WHEN x.key='lifecycle' THEN (SELECT coalesce(jsonb_agg(jsonb_build_object('event',e->>'event','rev',e->'rev')),'[]') FROM jsonb_array_elements(x.value)e WHERE e->>'event' IN('listing.sold','listing.delivered','sale.voided','listing.archived') AND jsonb_typeof(e->'rev')='number') ELSE x.value END),'{}') FROM jsonb_each(_value)x JOIN gw_source_authority a ON a.domain=_domain AND a.field=x.key AND a.owner_app=_owner AND a.shareable AND a.classification='internal' WHERE
 (jsonb_typeof(x.value) IN('number','boolean') OR (jsonb_typeof(x.value)='string' AND length(x.value#>>'{}')<=256 AND (x.key NOT IN('evidence_ref','service_visit_ref','object_ref') OR x.value#>>'{}' ~ '^[A-Za-z0-9._:/-]{1,256}$')) OR (x.key='approval' AND jsonb_typeof(x.value)='object') OR (x.key='lifecycle' AND jsonb_typeof(x.value)='array') OR (x.key='evidence_refs' AND jsonb_typeof(x.value)='array' AND jsonb_array_length(x.value) BETWEEN 1 AND 20 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(x.value)e WHERE jsonb_typeof(e)<>'string' OR e#>>'{}' !~ '^[A-Za-z0-9._:/-]{1,256}$')));
$$;
REVOKE ALL ON FUNCTION public.gw_exchange_safe_fact(jsonb,text,public.gw_app) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.gw_exchange_safe_fact(jsonb,text,public.gw_app) TO service_role;
CREATE FUNCTION public.gw_exchange_owned_service(_tenant text,_instance text,_episode text,_target public.gw_app) RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$
WITH delivered AS (SELECT o.*,o.envelope->'payload'||coalesce(o.envelope->'refs','{}')||jsonb_build_object('rev',o.aggregate_revision) AS val FROM gw_outbox o JOIN gw_queue q ON q.event_id=o.event_id AND q.target_app=_target AND q.status='delivered' JOIN gw_inbox i ON i.event_id=o.event_id AND i.target_app=q.target_app AND i.tenant_id=o.tenant_id AND i.result='applied' WHERE o.tenant_id=_tenant AND o.source_app='autofilm' AND o.aggregate_type='vehicle_instance' AND o.aggregate_id=_instance AND o.instance_id=_instance AND o.episode_id=_episode AND o.event_type IN('service.mpi_verified','service.repair_verified')), verified AS (SELECT * FROM delivered WHERE val->'technician_verified'='true' AND coalesce(val->>'service_visit_ref','')<>'' AND jsonb_typeof(val->'evidence_refs')='array' AND jsonb_array_length(val->'evidence_refs')>0 AND ((event_type='service.mpi_verified' AND val->>'reviewer_role' IN('service_manager','shop_foreman','quality_reviewer') AND coalesce(val->>'reviewer_approved_at','')<>'') OR (event_type='service.repair_verified' AND coalesce(val->>'completed_at','')<>''))) SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM verified) THEN '{"unavailable":"current-episode independently verified service evidence required"}'::jsonb ELSE jsonb_strip_nulls(jsonb_build_object('mpi',(SELECT gw_exchange_safe_fact(val,'service','autofilm') FROM verified WHERE event_type='service.mpi_verified' ORDER BY aggregate_revision DESC LIMIT 1),'repairs',(SELECT coalesce(jsonb_agg(fact),'[]') FROM (SELECT DISTINCT ON(val->>'service_visit_ref') gw_exchange_safe_fact(val,'service','autofilm')fact FROM verified WHERE event_type='service.repair_verified' ORDER BY val->>'service_visit_ref',aggregate_revision DESC)s))) END;
$$;
REVOKE ALL ON FUNCTION public.gw_exchange_owned_service(text,text,text,public.gw_app) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.gw_exchange_owned_service(text,text,text,public.gw_app) TO service_role;
CREATE FUNCTION public.gw_exchange_owned_media(_tenant text,_instance text,_episode text,_target public.gw_app) RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$
WITH assets AS (SELECT DISTINCT ON(o.envelope->'payload'->>'media_id') o.envelope->'payload'||jsonb_build_object('rev',o.aggregate_revision)val FROM gw_outbox o JOIN gw_queue q ON q.event_id=o.event_id AND q.target_app=_target AND q.status='delivered' JOIN gw_inbox i ON i.event_id=o.event_id AND i.target_app=q.target_app AND i.tenant_id=o.tenant_id AND i.result='applied' WHERE o.tenant_id=_tenant AND o.source_app='autoframe' AND o.aggregate_type='vehicle_instance' AND o.aggregate_id=_instance AND o.instance_id=_instance AND o.episode_id=_episode AND o.event_type='media.approved' ORDER BY o.envelope->'payload'->>'media_id',o.aggregate_revision DESC) SELECT coalesce(jsonb_agg(gw_exchange_safe_fact(val,'media','autoframe') ORDER BY (val->>'preset_order')::int),'[]') FROM assets WHERE val->>'object_ref' ~ '^objref:[A-Za-z0-9_-]+/[A-Za-z0-9._/-]+$' AND val->>'object_ref' NOT LIKE '%..%' AND val->>'mime' IN('image/jpeg','image/png','image/webp') AND val->>'content_sha256' ~ '^[a-f0-9]{64}$' AND val->'approval'->>'role' IN('sales_manager','inventory_manager','general_manager');
$$;
REVOKE ALL ON FUNCTION public.gw_exchange_owned_media(text,text,text,public.gw_app) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.gw_exchange_owned_media(text,text,text,public.gw_app) TO service_role;
DO $$ DECLARE def text; a int; b int; old text; BEGIN
 def:=pg_get_functiondef('public.gw_read_exchange(text,text,timestamptz,text,text,public.gw_app,text,jsonb)'::regprocedure);
 old:='SELECT * INTO k FROM gw_ingest_keys WHERE key_id=_key_id;'; IF position(old IN def)=0 THEN RAISE EXCEPTION 'identity anchor missing';END IF;
 def:=replace(def,old,'SELECT * INTO k FROM gw_ingest_keys WHERE key_id=_key_id FOR UPDATE;');
 def:=replace(def,'ELSIF _ts IS NULL','ELSIF k.key_usage IS DISTINCT FROM ''read_only'' THEN reason:=''read-only exchange identity required'';status:=403; ELSIF _ts IS NULL');
 def:=replace(def,'PERFORM 1 FROM gw_ingest_keys WHERE key_id=_key_id FOR UPDATE;','');
 def:=replace(def,'FROM gw_read_exchange_grants WHERE key_id=_key_id AND source_app=_source;','FROM gw_read_exchange_grants WHERE key_id=_key_id AND source_app=_source FOR UPDATE;');
 def:=replace(def,'key_id=_key_id AND mode=''exchange'' AND created_at','key_id=_key_id AND purpose=_purpose AND mode=''exchange'' AND decision=''ok'' AND created_at');
 def:=replace(def,'LIMIT 10 LOOP','LIMIT 51 LOOP');
 def:=replace(def,'SELECT id INTO cur_epi','IF rows_n>=50 THEN reason:=''response exceeds 50 instances; supply instance_id'';status:=400;EXIT;END IF; SELECT id INTO cur_epi');
 def:=replace(def,'stale:=expected=0 OR lag>0 OR br;','stale:=expected=0 OR lag>0 OR br OR cur_epi IS NULL;');
 old:='applied:=greatest(applied,coalesce((chosen.source_revisions->>(_source::text||'':vehicle_instance''))::bigint,0));';IF position(old IN def)=0 THEN RAISE EXCEPTION 'section revision anchor missing';END IF;
 def:=replace(def,old,'applied:=coalesce((chosen.source_revisions->>(_source::text||'':vehicle_instance''))::bigint,0); stale:=stale OR applied<>expected;');
 def:=replace(def,'IF v_value->>''source'' IS DISTINCT FROM','IF cur_epi IS NULL OR v_value->>''source'' IS DISTINCT FROM');
 old:='ELSE SELECT coalesce(jsonb_object_agg(x.key,x.value),''{}'') INTO safe FROM jsonb_each(v_value) x JOIN gw_source_authority a ON a.domain=v_domain AND a.field=x.key AND a.owner_app=_source AND a.shareable AND a.classification=''internal'';END IF;';IF position(old IN def)=0 THEN RAISE EXCEPTION 'listing shape anchor missing';END IF;
 def:=replace(def,old,'ELSE safe:=gw_exchange_safe_fact(v_value,v_domain,_source);END IF;');
 def:=replace(def,'''lifecycle'',h->''lifecycle''','''lifecycle'',gw_exchange_safe_fact(h,''listing'',_source)->''lifecycle''');
 a:=position('ELSIF sec=''media'' THEN' IN def);b:=position('ELSIF sec=''service'' THEN' IN def);IF a=0 OR b<=a THEN RAISE EXCEPTION 'media anchors missing';END IF;
 def:=substr(def,1,a-1)||'ELSIF sec=''media'' THEN safe:=gw_exchange_owned_media(_tenant,inst.id,cur_epi,chosen.target_app); '||substr(def,b);
 def:=replace(def,'safe:=gw_exchange_service(chosen.state);','safe:=gw_exchange_owned_service(_tenant,inst.id,cur_epi,chosen.target_app);');
 def:=replace(def,'o.aggregate_id=inst.id AND o.event_type=''appraisal.completed''','o.aggregate_type=''vehicle_instance'' AND o.aggregate_id=inst.id AND o.instance_id=inst.id AND o.episode_id=cur_epi AND o.event_type=''appraisal.completed''');
 def:=replace(def,'o.aggregate_id=inst.id AND o.event_type=''acquisition.closed''','o.aggregate_type=''vehicle_instance'' AND o.aggregate_id=inst.id AND o.instance_id=inst.id AND o.episode_id=cur_epi AND o.event_type=''acquisition.closed''');
 def:=replace(def,'WHERE q.event_id=o.event_id AND q.status=''delivered''','WHERE q.event_id=o.event_id AND q.target_app=chosen.target_app AND q.status=''delivered'' AND EXISTS(SELECT 1 FROM gw_inbox i WHERE i.event_id=o.event_id AND i.target_app=q.target_app AND i.tenant_id=_tenant AND i.result=''applied'')');
 def:=replace(def,'SELECT coalesce(jsonb_object_agg(x.key,x.value),''{}'') INTO safe FROM jsonb_each(v_value)x JOIN gw_source_authority a ON a.domain=v_domain AND a.field=x.key AND a.owner_app=_source AND a.shareable AND a.classification=''internal'';','safe:=gw_exchange_safe_fact(v_value,v_domain,_source);');
 def:=replace(def,'stale:=stale OR applied<expected;','');
 EXECUTE def;
END $$;
CREATE INDEX gw_exchange_budget_window ON public.gw_read_audit(key_id,purpose,created_at) WHERE mode='exchange' AND decision='ok';